// Push-only worker. Never caches staff pages, credentials or private responses.
self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
async function account(value){const cache=await caches.open('cage-push-account');if(value!==undefined)await cache.put('/__push_account',new Response(JSON.stringify(value)));const r=await cache.match('/__push_account');return r?await r.json():undefined;}
self.addEventListener('message',e=>{if(e.data?.type==='account')e.waitUntil(account(e.data.user));});
self.addEventListener('push',e=>e.waitUntil((async()=>{let data;try{data=e.data.json();}catch{return;}const user=await account();if(user===null||user&&user!==data.user)return;await self.registration.showNotification('CAGE · '+data.title,{body:'Open CAGE to view this update.',tag:data.id,icon:'/cage-favicon.png',data:{id:data.id}});})()));
self.addEventListener('notificationclick',e=>{e.notification.close();e.waitUntil((async()=>{const id=e.notification.data?.id;if(!id)return;const url=new URL('/',self.location.origin);url.searchParams.set('notification',id);const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});const tab=windows.find(w=>new URL(w.url).origin===self.location.origin&&!new URL(w.url).pathname.includes('partner'));if(tab){await tab.focus();tab.postMessage({type:'open-notification',id});}else await self.clients.openWindow(url.href);})());});
